{
  "technical_and_design_decisions": [
    "Use the existing project build system and Gradle conventions, extending them rather than introducing a new build framework.",
    "Package the custom module as an executable uber-jar with dependency merging and reproducible artifact naming.",
    "Publish or copy the uber-jar to a configurable HDFS location, with deployment documentation for newly arriving containers.",
    "Implement the WebSocket sink using the framework's supported native WebSocket APIs and make endpoint, buffer, and connection settings configurable.",
    "Use dependency caching in CI where supported, while retaining a fallback path that can build without a warm cache.",
    "Implement EC2 CI changes as version-controlled Gradle and CI configuration changes, including distributed JVM tests, command-based Gradle invocation, disabled embedded Hadoop tests, and increased parallel forks.",
    "Configure Sonar and PMD reporting so violations are visible in CI and notifications are sent to the committer or build-result notification channel.",
    "Use the existing Bamboo host and PowerShell-based Windows agents for automated Windows integration testing.",
    "Adopt the documented shared xd/lib location for common jars and require module-local bundling when incompatible dependency versions are needed."
  ],
  "assumptions": [
    "An existing Java/Spring codebase, custom-module skeleton, Gradle build, and test framework are available.",
    "The implementation targets Java 17 or later and the currently supported Spring Framework version.",
    "The WebSocket sink is a new or incomplete module feature, but the surrounding sink interfaces and application configuration patterns already exist.",
    "HDFS, Bamboo, EC2 CI agents, Sonar, and required Windows services can be accessed by the developer; provisioning corporate accounts and networking is out of scope.",
    "The required services for Windows integration tests, such as Redis and RabbitMQ, can be installed or started using existing scripts or standard installers.",
    "No changes are required to the Hadoop, container orchestration, or Bamboo product source code.",
    "Security hardening, TLS certificate procurement, production-scale performance testing, and multi-region deployment are out of scope.",
    "The estimates include implementation, configuration, documentation, and developer-level verification, but not elapsed waiting time for external approvals or infrastructure availability.",
    "The specification does not provide detailed WebSocket message semantics, so the implementation will follow existing project conventions and preserve the sink's established payload format.",
    "One developer performs the work, with normal code review and CI execution treated as part of the development effort."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Requirements analysis and implementation design",
      "activity_description": "Review the existing module architecture, build files, deployment conventions, CI configuration, test suites, and the eight user stories; define interfaces, configuration points, acceptance checks, and implementation sequencing.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A2",
      "activity_name": "Documentation and recommended implementation patterns",
      "activity_description": "Create or update developer documentation covering custom-module structure, recommended Spring patterns, build and packaging conventions, WebSocket sink usage, deployment expectations, and operational configuration.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A3",
      "activity_name": "Uber-jar packaging and HDFS hosting support",
      "activity_description": "Configure Gradle packaging for the custom module as an uber-jar, resolve resource and dependency merge issues, define artifact naming and versioning, and add documented commands or scripts for placing the artifact in HDFS for container deployment.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A4",
      "activity_name": "Native WebSocket sink implementation",
      "activity_description": "Implement or complete the native WebSocket sink, including endpoint and connection configuration, message forwarding, lifecycle and error handling, reconnect behavior consistent with project conventions, and unit or integration tests for full-duplex communication.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A5",
      "activity_name": "CI dependency-cache investigation and implementation",
      "activity_description": "Evaluate the proposed npm-cache approach and the existing CI dependency behavior, select a compatible caching strategy, implement cache configuration or scripts, and verify cache-hit and cache-miss builds without making the build dependent on a populated cache.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A6",
      "activity_name": "EC2 CI infrastructure improvements",
      "activity_description": "Enable distributed JVM tests, replace the Artifactory Gradle task with a command task invoking ./gradlew, disable embedded Hadoop for the specified tests, enable maxParallelForks, and validate build stability and test execution on EC2 CI agents.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A7",
      "activity_name": "WARN log, PMD, and Sonar investigation",
      "activity_description": "Trace the increase in WARN logs, distinguish actionable defects from expected warnings, fix relevant PMD and Sonar violations, update analysis configuration where appropriate, and configure committer-facing violation notifications.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A8",
      "activity_name": "Windows Bamboo integration-test setup",
      "activity_description": "Configure the existing Bamboo Windows environment, verify PowerShell access, automate setup or startup of required services such as Redis and RabbitMQ, add the commit-triggered CI task, and validate successful Windows integration-test execution and failure reporting.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A9",
      "activity_name": "Shared dependency-jar location and classloader guidance",
      "activity_description": "Document and configure the common xd/lib dependency location, verify loading of jars shared by multiple custom modules, add guidance and checks for version conflicts, and validate module-local bundling for incompatible dependency versions.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A10",
      "activity_name": "End-to-end verification and regression testing",
      "activity_description": "Run focused unit, integration, packaging, HDFS deployment, WebSocket, Linux CI, and Windows CI checks; diagnose failures caused by the increment; verify acceptance criteria; and perform a final regression pass.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A11",
      "activity_name": "Release preparation and handoff",
      "activity_description": "Finalize configuration examples, CI and deployment instructions, known limitations, artifact publication details, and change notes; clean up scripts and prepare the increment for review and release.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 320
  }
}

